#!/usr/bin/env python3
"""Rebuild the self-contained treer-setup.sh, or --check it matches its sources."""
import argparse
from pathlib import Path
import sys

FILES = ("setup.sh", "install.py", "configure.py", "profiles.json")
NAME = "treer-setup.sh"


def generate(directory):
    result = """#!/bin/sh
# Generated by integrations/treer/bundle_setup.py; edit its four source files.
# Downloads only pinned runtime release assets, never another setup script.
set -eu
umask 077
bundle_dir=$(mktemp -d "${TMPDIR:-/tmp}/pockymoe-treer.XXXXXX")
trap 'rm -rf "$bundle_dir"' 0
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM
echo 'Pockymoe setup: unpacking bundled setup into a private temporary directory.'
"""
    for name in FILES:
        source = (directory / name).read_text()
        delimiter = "POCKYMOE_BUNDLE_" + name.replace(".", "_").upper()
        if not source.endswith("\n") or delimiter in source.splitlines():
            raise ValueError(f"Cannot bundle {name}: missing final newline or heredoc delimiter collision")
        result += f'cat > "$bundle_dir/{name}" <<\'{delimiter}\'\n{source}{delimiter}\n'
    return result + 'sh "$bundle_dir/setup.sh" "$@"\n'


def check(directory):
    if (directory / NAME).read_text() != generate(directory):
        raise ValueError("Stale Treer setup bundle; run python3 integrations/treer/bundle_setup.py")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    directory = Path(__file__).parent
    if args.check:
        try:
            check(directory)
        except (OSError, ValueError) as error:
            print(str(error), file=sys.stderr)
            return 1
        print("Treer setup bundle matches all four source files.")
    else:
        (directory / NAME).write_text(generate(directory))
    return 0


if __name__ == "__main__":
    sys.exit(main())
